-- ===== BEGIN 20261266000000_driver_cash_credit_market_pilot.sql =====
-- Market-scoped cash-ride pilot (generated by scripts/generate-cash-credit-market-pilot.cjs).
-- Before: one GLOBAL switch (driver_cash_credit_config_v1e.ride_cash_credit) turned cash-ride credit
-- enforcement on for every market at once. After: enforcement applies to a country/currency only
-- when the global switch is on AND that market has an enabled row here AND the currency matches
-- market_availability. The global switch remains the kill switch. Markets without a row keep the
-- existing (non-pilot) behaviour. This migration enables NO market. Privileges mirror the global switch:
-- the table is written only by the database owner; the check is executable by service_role only.
-- Replaced functions are the deployed bodies with only the pilot check changed.

CREATE TABLE public.driver_cash_credit_markets_v1e (
    country_code text NOT NULL CHECK (country_code ~ '^[A-Z]{2}$'),
    currency_code text NOT NULL CHECK (currency_code ~ '^[A-Z]{3}$'),
    enabled boolean NOT NULL DEFAULT false,
    note text CHECK (note IS NULL OR length(note) <= 200),
    updated_at timestamp with time zone NOT NULL DEFAULT now(),
    PRIMARY KEY (country_code, currency_code)
);
ALTER TABLE public.driver_cash_credit_markets_v1e ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.driver_cash_credit_markets_v1e FROM PUBLIC;
DO $g$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON TABLE public.driver_cash_credit_markets_v1e FROM anon; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON TABLE public.driver_cash_credit_markets_v1e FROM authenticated; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN REVOKE ALL ON TABLE public.driver_cash_credit_markets_v1e FROM service_role; END IF;
END $g$;

CREATE FUNCTION public.driver_cash_credit_market_enabled_v1e(p_country text, p_currency text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT public.driver_cash_credit_enabled_v1e()
  AND EXISTS (SELECT 1 FROM public.driver_cash_credit_markets_v1e m
              WHERE m.country_code=upper(p_country) AND m.currency_code=upper(p_currency) AND m.enabled)
  AND EXISTS (SELECT 1 FROM public.market_availability a
              WHERE a.country_code=upper(p_country) AND upper(a.supported_currency)=upper(p_currency)) $$;
REVOKE ALL ON FUNCTION public.driver_cash_credit_market_enabled_v1e(text, text) FROM PUBLIC;
DO $g$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON FUNCTION public.driver_cash_credit_market_enabled_v1e(text, text) FROM anon; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON FUNCTION public.driver_cash_credit_market_enabled_v1e(text, text) FROM authenticated; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN GRANT EXECUTE ON FUNCTION public.driver_cash_credit_market_enabled_v1e(text, text) TO service_role; END IF;
END $g$;

CREATE OR REPLACE FUNCTION public.driver_cash_credit_status_v1f(p_driver_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE p public.profiles%ROWTYPE; v_country text; v_currency text; currencies integer; approved boolean; b jsonb;
BEGIN
 SELECT * INTO p FROM public.profiles WHERE id=p_driver_id;
 IF NOT FOUND OR p.role IS DISTINCT FROM 'driver' THEN RAISE EXCEPTION 'Driver access required' USING ERRCODE='CE002'; END IF;
 v_country:=upper(btrim(coalesce(nullif(p.registration_country_code,''),p.country_code,'')));
 IF p.tenant_id IS NULL OR v_country !~ '^[A-Z]{2}$' THEN RAISE EXCEPTION 'Driver market unresolved' USING ERRCODE='CE002'; END IF;
 SELECT count(DISTINCT upper(supported_currency)),min(upper(supported_currency)) INTO currencies,v_currency
 FROM public.market_availability WHERE country_code=v_country;
 IF currencies<>1 OR v_currency IS NULL OR v_currency !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'Driver currency unresolved' USING ERRCODE='CE002'; END IF;
 approved:=p.registration_activated_at IS NOT NULL AND EXISTS(
  SELECT 1 FROM public.driver_cash_credit_enrolments_v1e e WHERE e.tenant_id=p.tenant_id AND e.driver_id=p.id
   AND e.country_code=v_country AND e.currency_code=v_currency AND e.enabled AND e.consented_at<=now());
 b:=public.driver_cash_credit_balance_v1e(p.tenant_id,p.id,v_currency);
 RETURN jsonb_build_object('tenantId',p.tenant_id,'driverId',p.id,'country',v_country,'currency',v_currency,
  'pilotEnabled',public.driver_cash_credit_market_enabled_v1e(v_country,v_currency),'enrolled',approved,'balance',b,
  'topupAvailable',false,'payoutAvailable',false,'acceptanceAuthority','database');
END $_$;

CREATE OR REPLACE FUNCTION public.enforce_ride_cash_credit_v1e() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE h public.driver_cash_credit_holds_v1e%ROWTYPE; driver uuid; slug text;
BEGIN
 SELECT * INTO h FROM public.driver_cash_credit_holds_v1e WHERE job_id=NEW.id;
 IF FOUND THEN
  IF NOT public.cash_credit_service_writer_v1e() THEN RAISE EXCEPTION 'Cash transitions require the server role' USING ERRCODE='CE002'; END IF;
  IF NEW.status IS NULL THEN RAISE EXCEPTION 'Cash booking status missing' USING ERRCODE='CE006'; END IF;
  IF NEW.status IN ('cancelled','canceled','expired','failed','no_driver_found') THEN
   IF h.status='settled' THEN RAISE EXCEPTION 'Settled cash ride requires refund review' USING ERRCODE='CE005'; END IF;
   IF h.status='held' THEN PERFORM public.resolve_cash_job_credit_v1e(NEW.id,'released'); END IF;
   RETURN NEW;
  END IF;
  IF h.status='released' OR (h.status='settled' AND NEW.status NOT IN ('completed','delivered','settled')) THEN RAISE EXCEPTION 'Resolved cash ride cannot reopen' USING ERRCODE='CE005'; END IF;
  IF NEW.driver_id IS NOT NULL AND NEW.accepted_driver_id IS NOT NULL AND NEW.driver_id<>NEW.accepted_driver_id THEN RAISE EXCEPTION 'Conflicting accepted drivers' USING ERRCODE='CE005'; END IF;
  IF NEW.metadata->>'cash_collection_mode' IS DISTINCT FROM 'full_customer_charge' OR NEW.payment_intent_id IS NOT NULL THEN RAISE EXCEPTION 'Cash custody/payment mode changed' USING ERRCODE='CE005'; END IF;
  IF NEW.payment_method IS DISTINCT FROM 'cash' OR NEW.fare_breakdown IS DISTINCT FROM h.fare_snapshot
     OR NEW.tenant_id IS DISTINCT FROM h.tenant_id OR NEW.currency_code IS DISTINCT FROM h.currency_code
     OR NEW.country_code IS DISTINCT FROM h.country_code OR coalesce(NEW.driver_id,NEW.accepted_driver_id) IS DISTINCT FROM h.driver_id THEN
   RAISE EXCEPTION 'Cash reservation requires explicit reconciliation before changing terms' USING ERRCODE='CE005'; END IF;
  IF NEW.status IN ('completed','delivered','settled') AND h.status='held' THEN PERFORM public.resolve_cash_job_credit_v1e(NEW.id,'settled'); END IF;
  RETURN NEW;
 END IF;
 IF NEW.payment_method IS DISTINCT FROM 'cash' OR NOT public.driver_cash_credit_market_enabled_v1e(NEW.country_code,NEW.currency_code) THEN RETURN NEW; END IF;
 SELECT st.slug INTO slug FROM public.service_types st WHERE st.id=NEW.service_type_id;
 IF slug IS DISTINCT FROM 'ride' THEN RETURN NEW; END IF;
 IF NOT public.cash_credit_service_writer_v1e() THEN RAISE EXCEPTION 'Cash acceptance requires the server role' USING ERRCODE='CE002'; END IF;
 driver:=coalesce(NEW.driver_id,NEW.accepted_driver_id);
 IF driver IS NOT NULL AND NEW.status IN ('assigned','accepted','heading_to_pickup','driver_en_route','arrived','in_progress','completed','delivered','settled') THEN
  PERFORM public.reserve_cash_job_credit_v1e(NEW.id,driver);
 END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.reserve_cash_job_credit_v1e(p_job_id uuid, p_driver_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE j public.jobs%ROWTYPE; enrol public.driver_cash_credit_enrolments_v1e%ROWTYPE; p jsonb; terms jsonb; balance jsonb; h public.driver_cash_credit_holds_v1e%ROWTYPE; v_id uuid; event uuid; need bigint; driver uuid;
BEGIN
 SELECT * INTO STRICT j FROM public.jobs WHERE id=p_job_id FOR UPDATE;
 IF NOT public.driver_cash_credit_market_enabled_v1e(j.country_code,j.currency_code) THEN RAISE EXCEPTION 'Cash credit pilot disabled for this market' USING ERRCODE='CE001'; END IF;
 driver:=coalesce(j.driver_id,j.accepted_driver_id);
 IF driver IS DISTINCT FROM p_driver_id OR p_driver_id IS NULL OR (j.driver_id IS NOT NULL AND j.accepted_driver_id IS NOT NULL AND j.driver_id<>j.accepted_driver_id)
 OR j.payment_method IS DISTINCT FROM 'cash' OR j.status IS NULL OR j.status NOT IN ('assigned','accepted','heading_to_pickup','driver_en_route','arrived','in_progress','completed','delivered','settled') THEN
  RAISE EXCEPTION 'Cash booking/driver is not eligible' USING ERRCODE='CE002'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.service_types WHERE id=j.service_type_id AND slug='ride') THEN
  RAISE EXCEPTION 'Cash credit pilot supports Ride only' USING ERRCODE='CE002'; END IF;
 PERFORM public.driver_cash_credit_lock_v1e(j.tenant_id,p_driver_id,j.currency_code);
 SELECT to_jsonb(x) INTO p FROM public.profiles x WHERE id=p_driver_id;
 SELECT * INTO enrol FROM public.driver_cash_credit_enrolments_v1e WHERE tenant_id=j.tenant_id AND driver_id=p_driver_id AND country_code=j.country_code AND currency_code=j.currency_code FOR SHARE;
 IF p IS NULL OR p->>'role' IS DISTINCT FROM 'driver' OR NULLIF(p->>'registration_activated_at','') IS NULL
 OR NOT public.driver_job_market_matches_v23(p,to_jsonb(j))
 OR NOT EXISTS(SELECT 1 FROM public.market_availability m WHERE m.country_code=j.country_code AND upper(m.supported_currency)=j.currency_code)
 OR enrol.driver_id IS NULL OR NOT enrol.enabled OR enrol.consented_at>now() THEN
  RAISE EXCEPTION 'Driver cash credit is not approved for this tenant/market' USING ERRCODE='CE002'; END IF;
 terms:=public.cash_credit_terms_v1e(j.fare_breakdown,j.currency_code);need:=(terms->>'required')::bigint;
 IF j.fare_breakdown ? 'driverCommissionPolicy' AND j.fare_breakdown->'driverCommissionPolicy'->>'driverId' IS DISTINCT FROM p_driver_id::text THEN
  RAISE EXCEPTION 'Frozen commission belongs to another driver' USING ERRCODE='CE003'; END IF;
 IF j.agreed_fare IS NOT NULL AND public.cash_credit_minor_v1e(to_jsonb(j.agreed_fare),j.currency_code)<>(terms->>'charge')::bigint THEN
  RAISE EXCEPTION 'Agreed fare does not match frozen cash terms' USING ERRCODE='CE003'; END IF;
 SELECT * INTO h FROM public.driver_cash_credit_holds_v1e WHERE job_id=j.id FOR UPDATE;
 IF FOUND THEN
  IF h.driver_id<>p_driver_id OR h.tenant_id<>j.tenant_id OR h.currency_code<>j.currency_code OR h.country_code<>j.country_code OR h.fare_snapshot IS DISTINCT FROM j.fare_breakdown OR h.status='released' THEN
   RAISE EXCEPTION 'Cash reservation replay terms changed' USING ERRCODE='CE005'; END IF;
  RETURN h.id;
 END IF;
 IF j.metadata->>'cash_collection_mode' IS DISTINCT FROM 'full_customer_charge' OR j.payment_intent_id IS NOT NULL OR j.payment_status IS NULL OR j.payment_status NOT IN ('pending','cash_due','cash_pending') THEN
  RAISE EXCEPTION 'Explicit full-cash custody and no digital payment required' USING ERRCODE='CE002'; END IF;
 IF j.status IN ('completed','delivered','settled') THEN RAISE EXCEPTION 'Cannot create a new cash hold after completion' USING ERRCODE='CE006'; END IF;
 balance:=public.driver_cash_credit_balance_v1e(j.tenant_id,p_driver_id,j.currency_code);
 IF NOT (balance->>'consistent')::boolean OR (balance->>'deficitMinor')::numeric>0 THEN RAISE EXCEPTION 'Cash credit requires reconciliation' USING ERRCODE='CE006'; END IF;
 IF (balance->>'availableMinor')::numeric<need THEN RAISE EXCEPTION 'Top up driver cash credit before accepting this cash ride' USING ERRCODE='CE004'; END IF;
 v_id:=gen_random_uuid();
 IF need>0 THEN
  event:=public.post_wallet_event('cash-hold:'||v_id::text,'cash_credit_reserve',j.tenant_id,p_driver_id,j.currency_code,
   jsonb_build_array(jsonb_build_object('accountPurpose','driver_cash_credit','amountMinor',-need),jsonb_build_object('accountPurpose','driver_cash_credit_reserved','amountMinor',need)));
 END IF;
 INSERT INTO public.driver_cash_credit_holds_v1e(id,job_id,tenant_id,driver_id,country_code,currency_code,fare_snapshot,enrolment_terms_version,enrolment_consented_at,customer_charge_minor,commission_minor,platform_fee_minor,driver_entitlement_minor,required_credit_minor,reserve_event_id)
 VALUES(v_id,j.id,j.tenant_id,p_driver_id,j.country_code,j.currency_code,j.fare_breakdown,enrol.terms_version,enrol.consented_at,(terms->>'charge')::bigint,(terms->>'commission')::bigint,(terms->>'fee')::bigint,(terms->>'net')::bigint,need,event);
 RETURN v_id;
END $$;


-- ===== END 20261266000000_driver_cash_credit_market_pilot.sql =====

-- ===== BEGIN 20261266100000_cash_ride_booking_fee_hold.sql =====
-- Cash-ride booking, phase 1 (generated by scripts/generate-cash-ride-booking-migration.cjs).
-- A cash Ride is secured by an on-session card HOLD for its fee terms (no-show / late
-- cancellation). The hold lives here, not in jobs.payment_intent_id, because cash-credit 1E
-- requires a cash job to carry no PaymentIntent. A driver may acquire a cash_due job only when
-- it is a cash Ride with full customer cash collection, in an ENABLED cash-ride pilot market,
-- with an authorised hold for that job, customer and currency. Card and wallet jobs are
-- unchanged. This migration enables no market.

-- Two cash payment states: cash_due (customer pays the driver in cash at the end of the ride;
-- the state cash-credit 1E reserves against) and cash_collected (completed cash ride).
ALTER TABLE public.jobs DROP CONSTRAINT jobs_payment_status_check;
ALTER TABLE public.jobs ADD CONSTRAINT jobs_payment_status_check CHECK (((payment_status IS NULL) OR (payment_status = ANY (ARRAY['pending'::text, 'authorized'::text, 'wallet_funded'::text, 'paid'::text, 'cancelled'::text, 'canceled'::text, 'refunded'::text, 'failed'::text, 'requires_refund'::text, 'requires_review'::text, 'cash_due'::text, 'cash_collected'::text]))));

CREATE TABLE public.cash_ride_fee_holds_v1e (
    job_id uuid PRIMARY KEY REFERENCES public.jobs(id),
    tenant_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    provider text NOT NULL CHECK (provider ~ '^[a-z][a-z0-9_-]{1,31}$'),
    merchant_account_ref text NOT NULL CHECK (length(btrim(merchant_account_ref)) BETWEEN 1 AND 100),
    provider_payment_reference text UNIQUE CHECK (provider_payment_reference IS NULL OR length(provider_payment_reference) BETWEEN 3 AND 255),
    amount_minor bigint NOT NULL CHECK (amount_minor > 0),
    currency_code text NOT NULL CHECK (currency_code ~ '^[A-Z]{3}$'),
    fee_terms jsonb NOT NULL,
    status text NOT NULL DEFAULT 'created' CHECK (status IN ('created','authorized','captured','released','failed')),
    captured_minor bigint NOT NULL DEFAULT 0 CHECK (captured_minor >= 0 AND captured_minor <= amount_minor),
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    updated_at timestamp with time zone NOT NULL DEFAULT now(),
    CHECK (status <> 'authorized' OR provider_payment_reference IS NOT NULL),
    CHECK (status = 'captured' OR captured_minor = 0)
);
ALTER TABLE public.cash_ride_fee_holds_v1e ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.cash_ride_fee_holds_v1e FROM PUBLIC;
DO $g$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON TABLE public.cash_ride_fee_holds_v1e FROM anon; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON TABLE public.cash_ride_fee_holds_v1e FROM authenticated; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN
    REVOKE ALL ON TABLE public.cash_ride_fee_holds_v1e FROM service_role;
    GRANT SELECT, INSERT, UPDATE ON TABLE public.cash_ride_fee_holds_v1e TO service_role;
  END IF;
END $g$;

CREATE FUNCTION public.cash_ride_acquirable_v1e(j public.jobs) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 -- Strictly true/false: a NULL here would make the trigger's NOT ... evaluate to NULL and let
 -- the acquisition through.
 SELECT coalesce((j.payment_method = 'cash'
  AND j.payment_status = 'cash_due'
  AND j.payment_intent_id IS NULL
  AND j.metadata->>'cash_collection_mode' = 'full_customer_charge'
  AND EXISTS (SELECT 1 FROM public.service_types s WHERE s.id = j.service_type_id AND s.slug = 'ride')
  AND coalesce(public.driver_cash_credit_market_enabled_v1e(j.country_code, j.currency_code), false)
  AND EXISTS (SELECT 1 FROM public.cash_ride_fee_holds_v1e h
              WHERE h.job_id = j.id AND h.status = 'authorized' AND h.customer_id = j.customer_id
                AND h.tenant_id = j.tenant_id AND h.currency_code = j.currency_code)), false) $$;
REVOKE ALL ON FUNCTION public.cash_ride_acquirable_v1e(public.jobs) FROM PUBLIC;
DO $g$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON FUNCTION public.cash_ride_acquirable_v1e(public.jobs) FROM anon; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON FUNCTION public.cash_ride_acquirable_v1e(public.jobs) FROM authenticated; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN GRANT EXECUTE ON FUNCTION public.cash_ride_acquirable_v1e(public.jobs) TO service_role; END IF;
END $g$;

CREATE OR REPLACE FUNCTION public.enforce_job_payment_eligibility() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.driver_id IS NOT NULL
       AND OLD.driver_id IS DISTINCT FROM NEW.driver_id
       AND NEW.status IN ('assigned', 'accepted') THEN
        IF NEW.payment_status NOT IN (
            'paid', 'wallet_funded', 'authorized', 'requires_capture', 'succeeded', 'captured'
        ) AND NOT public.cash_ride_acquirable_v1e(NEW) THEN
            RAISE EXCEPTION 'Job is not payment-eligible for driver acquisition'
                USING ERRCODE = 'MB003',
                      DETAIL = 'payment_eligibility';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


-- ===== END 20261266100000_cash_ride_booking_fee_hold.sql =====

-- ===== BEGIN 20261266200000_cash_ride_activation.sql =====
-- Cash-ride booking phase 2 (generated by scripts/generate-cash-ride-activation-migration.cjs).
-- 1. activate_cash_ride_v1e: in ONE transaction, with the job and its fee hold locked, proves the
--    job is an activatable cash Ride and the hold is exactly the server-created one, marks the
--    hold authorised and starts the driver search (same dispatch fields as card activation).
-- 2. Drivers can see unassigned cash_due jobs (the deployed policy plus 'cash_due' only).
--    Acquisition stays guarded by enforce_job_payment_eligibility / cash_ride_acquirable_v1e.

CREATE FUNCTION public.activate_cash_ride_v1e(p_job_id uuid, p_customer_id uuid, p_provider text,
    p_provider_payment_reference text, p_amount_minor bigint, p_currency text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE j public.jobs%ROWTYPE; h public.cash_ride_fee_holds_v1e%ROWTYPE;
BEGIN
 SELECT * INTO j FROM public.jobs WHERE id = p_job_id FOR UPDATE;
 IF NOT FOUND THEN RETURN 'not_found'; END IF;
 IF j.customer_id IS DISTINCT FROM p_customer_id THEN RETURN 'not_owner'; END IF;
 SELECT * INTO h FROM public.cash_ride_fee_holds_v1e WHERE job_id = p_job_id FOR UPDATE;
 IF NOT FOUND THEN RETURN 'no_hold'; END IF;
 IF h.status = 'authorized' AND h.provider_payment_reference = p_provider_payment_reference
    AND j.status IN ('searching','assigned','accepted','heading_to_pickup','driver_en_route','arrived','in_progress','completed') THEN
  RETURN 'already_activated';
 END IF;
 IF j.status IS DISTINCT FROM 'requested' OR j.driver_id IS NOT NULL OR j.accepted_driver_id IS NOT NULL
    OR j.payment_method IS DISTINCT FROM 'cash' OR j.payment_status IS DISTINCT FROM 'cash_due' OR j.payment_intent_id IS NOT NULL
    OR j.metadata->>'cash_collection_mode' IS DISTINCT FROM 'full_customer_charge'
    OR (j.scheduled_time IS NOT NULL AND j.scheduled_time > now() + interval '5 minutes')
    OR NOT EXISTS (SELECT 1 FROM public.service_types s WHERE s.id = j.service_type_id AND s.slug = 'ride')
    OR NOT coalesce(public.driver_cash_credit_market_enabled_v1e(j.country_code, j.currency_code), false) THEN
  RETURN 'not_activatable';
 END IF;
 IF h.status IS DISTINCT FROM 'created' OR h.provider IS DISTINCT FROM p_provider
    OR h.provider_payment_reference IS DISTINCT FROM p_provider_payment_reference
    OR h.amount_minor IS DISTINCT FROM p_amount_minor OR h.currency_code IS DISTINCT FROM upper(p_currency)
    OR h.customer_id IS DISTINCT FROM j.customer_id OR h.tenant_id IS DISTINCT FROM j.tenant_id
    OR h.currency_code IS DISTINCT FROM j.currency_code THEN
  RETURN 'hold_mismatch';
 END IF;
 UPDATE public.cash_ride_fee_holds_v1e SET status = 'authorized', updated_at = now() WHERE job_id = p_job_id;
 UPDATE public.jobs SET status = 'searching', dispatch_started_at = now(),
   driver_search_expires_at = now() + interval '5 minutes', dispatch_attempts = 1
 WHERE id = p_job_id;
 RETURN 'activated';
END $$;
REVOKE ALL ON FUNCTION public.activate_cash_ride_v1e(uuid, uuid, text, text, bigint, text) FROM PUBLIC;
DO $g$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON FUNCTION public.activate_cash_ride_v1e(uuid, uuid, text, text, bigint, text) FROM anon; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON FUNCTION public.activate_cash_ride_v1e(uuid, uuid, text, text, bigint, text) FROM authenticated; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN GRANT EXECUTE ON FUNCTION public.activate_cash_ride_v1e(uuid, uuid, text, text, bigint, text) TO service_role; END IF;
END $g$;

DROP POLICY "Users can view relevant jobs" ON public.jobs;
CREATE POLICY "Users can view relevant jobs" ON public.jobs FOR SELECT USING (((auth.uid() = customer_id) OR (auth.uid() = driver_id) OR ((driver_id IS NULL) AND (status = ANY (ARRAY['pending'::text, 'requested'::text, 'searching'::text])) AND (payment_status = ANY (ARRAY['pending'::text, 'authorized'::text, 'wallet_funded'::text, 'paid'::text, 'cash_due'::text])) AND ((driver_search_expires_at IS NULL) OR (driver_search_expires_at > now()))) OR (EXISTS ( SELECT 1
   FROM public.tenant_users
  WHERE ((tenant_users.user_id = auth.uid()) AND (tenant_users.role = 'admin'::text) AND (tenant_users.tenant_id = jobs.tenant_id))))));


-- ===== END 20261266200000_cash_ride_activation.sql =====

-- ===== BEGIN 20261266300000_cash_ride_completion.sql =====
-- Cash-ride booking phase 3: atomic completion of a cash Ride.
-- One transaction, with the job locked: proves it is this driver's in-progress cash Ride with
-- full cash custody and no PaymentIntent, re-validates the frozen canonical fare
-- (cash_credit_terms_v1e), marks it completed / cash_collected, and records the driver's earnings
-- as a cash ride (status paid: the driver already holds the cash; no transfer, no payout queue).
-- The deployed cash-credit trigger (enforce_ride_cash_credit_v1e) settles the commission + fee
-- hold in the same transaction. Idempotent: a repeat returns the completed job unchanged.
-- New function only; no deployed object is replaced.

CREATE FUNCTION public.complete_cash_ride_v1e(p_job_id uuid, p_driver_id uuid, p_metadata jsonb) RETURNS SETOF public.jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE j public.jobs%ROWTYPE; b jsonb; t jsonb;
BEGIN
 SELECT * INTO STRICT j FROM public.jobs WHERE id = p_job_id FOR UPDATE;
 IF coalesce(j.driver_id, j.accepted_driver_id) IS DISTINCT FROM p_driver_id THEN
  RAISE EXCEPTION 'Only the assigned driver can complete this request'; END IF;
 IF j.payment_method IS DISTINCT FROM 'cash' OR j.payment_intent_id IS NOT NULL
    OR j.metadata->>'cash_collection_mode' IS DISTINCT FROM 'full_customer_charge' THEN
  RAISE EXCEPTION 'Not a cash ride'; END IF;
 IF j.status = 'completed' AND j.payment_status = 'cash_collected' THEN
  IF EXISTS (SELECT 1 FROM public.driver_earnings e WHERE e.job_id = p_job_id AND e.settlement_purpose = 'cash_ride' AND e.driver_id = p_driver_id) THEN
   RETURN QUERY SELECT * FROM public.jobs WHERE id = p_job_id; RETURN;
  END IF;
  RAISE EXCEPTION 'Completed cash ride requires reconciliation';
 END IF;
 IF j.payment_status IS DISTINCT FROM 'cash_due' THEN RAISE EXCEPTION 'Cash ride payment state requires reconciliation'; END IF;
 IF j.status NOT IN ('in_progress','en_route_to_customer','arrived_at_customer','on_trip') THEN
  RAISE EXCEPTION 'Request is not ready for completion'; END IF;
 IF coalesce(p_metadata->>'completion_pin_verified_at','') = '' THEN RAISE EXCEPTION 'Verified completion evidence missing'; END IF;
 IF EXISTS (SELECT 1 FROM public.job_payout_queue q WHERE q.job_id = p_job_id) THEN
  RAISE EXCEPTION 'A payout entry for a cash ride requires reconciliation'; END IF;
 b := j.fare_breakdown;
 t := public.cash_credit_terms_v1e(b, j.currency_code);   -- canonical frozen fare or CE003
 UPDATE public.jobs SET status = 'completed', payment_status = 'cash_collected', completed_at = coalesce(completed_at, now()),
   driver_payout = (b->>'driverEntitlement')::numeric, platform_fee = (b->>'platformFeeAmount')::numeric,
   commission_fee = (b->>'driverCommissionAmount')::numeric, commission_rate_used = (b->>'commissionPercent')::numeric,
   metadata = coalesce(j.metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb)
     || jsonb_build_object('cash_collected', true, 'cash_collected_minor', (t->>'charge')::bigint), updated_at = now()
 WHERE id = p_job_id;
 INSERT INTO public.driver_earnings(driver_id, job_id, amount, platform_fee, gross_amount, status, currency_code, country_code, settled_at, settlement_purpose)
 VALUES (p_driver_id, p_job_id, (b->>'driverEntitlement')::numeric, (b->>'platformFeeAmount')::numeric, (b->>'customerCharge')::numeric,
   'paid', j.currency_code, j.country_code, now(), 'cash_ride')
 ON CONFLICT (job_id) DO NOTHING;
 IF NOT FOUND THEN RAISE EXCEPTION 'Existing earnings for this job require reconciliation'; END IF;
 RETURN QUERY SELECT * FROM public.jobs WHERE id = p_job_id;
END $$;
REVOKE ALL ON FUNCTION public.complete_cash_ride_v1e(uuid, uuid, jsonb) FROM PUBLIC;
DO $g$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON FUNCTION public.complete_cash_ride_v1e(uuid, uuid, jsonb) FROM anon; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON FUNCTION public.complete_cash_ride_v1e(uuid, uuid, jsonb) FROM authenticated; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN GRANT EXECUTE ON FUNCTION public.complete_cash_ride_v1e(uuid, uuid, jsonb) TO service_role; END IF;
END $g$;


-- ===== END 20261266300000_cash_ride_completion.sql =====

-- ===== BEGIN 20261267000000_driver_cancellation_attribution.sql =====
-- Driver cancellation attribution + offer metrics from recorded events.
--
-- Policy D9 (user decisions, 2026-11-12): a driver-attributable cancellation is DRIVER-INITIATED
-- ONLY, decided by the server-verified actor, never by free text. Two driver-initiated actions:
--   * the ASSIGNED driver cancels the booking (POST /api/booking/cancel by the session driver);
--   * the driver voluntarily hands back an ACCEPTED assignment (POST /api/booking/driver-unable),
--     recorded as a 'declined' offer event after that offer's 'accepted' event (close_driver_offer).
--     A handback counts once as a driver cancellation and is also reported as driverHandoffs.
-- Customer, admin and system removals (incl. no-shows) never count; historical cancellations with no
-- recorded actor are reported separately as unattributed.
--
-- Metric identity and window: one ASSIGNMENT = (driver, job) accepted by this driver, counted once
-- however many offers or re-acceptances it took. The denominator is the driver's assignments whose
-- acceptance falls in the window; every numerator/exclusion class is a subset of exactly those
-- assignments and each assignment is classified once.
--
-- Additive: cancel_job_safely is unchanged and still callable; nothing is enabled.

-- 1) Cancellation with the verified actor recorded in the SAME transaction.
create or replace function public.cancel_job_with_actor(
  p_job_id uuid, p_reason text, p_actor uuid, p_actor_role text)
returns boolean language plpgsql security definer set search_path = public, pg_temp as $$
declare j public.jobs%rowtype; ok boolean;
begin
  if p_actor is null or p_actor_role is null or p_actor_role not in ('customer','driver','admin') then
    raise exception 'invalid cancellation actor' using errcode = '22023';
  end if;
  select * into strict j from public.jobs where id = p_job_id for update;
  if p_actor_role = 'driver' and j.driver_id is distinct from p_actor and j.accepted_driver_id is distinct from p_actor then
    raise exception 'cancellation actor is not the assigned driver' using errcode = '42501';
  end if;
  if p_actor_role = 'customer' and j.customer_id is distinct from p_actor then
    raise exception 'cancellation actor is not the customer' using errcode = '42501';
  end if;
  ok := public.cancel_job_safely(p_job_id, p_reason);
  -- Record the actor only for the call that actually cancelled. A repeat cancel of an already
  -- cancelled job returns true but never overwrites the original actor.
  if ok and j.status not in ('cancelled','canceled') then
    update public.jobs
       set metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
             'cancelled_by', p_actor, 'cancelled_by_role', p_actor_role, 'cancelled_driver_id', coalesce(j.driver_id, j.accepted_driver_id))
     where id = p_job_id;
  end if;
  return ok;
end $$;
revoke all on function public.cancel_job_with_actor(uuid,text,uuid,text) from public, anon, authenticated;
grant execute on function public.cancel_job_with_actor(uuid,text,uuid,text) to service_role;

-- 2) Negotiated acceptances (customer accepts a driver's bid / driver accepts a counter-offer) do not
--    pass through dispatch offers. Record them as an accepted assignment so they enter the same
--    denominator. Only when the driver actually owns the job now; idempotent (one 'negotiation' offer).
create or replace function public.record_negotiated_assignment(p_job uuid, p_driver uuid)
returns boolean language plpgsql security definer set search_path = public, pg_temp as $$
declare j public.jobs%rowtype;
begin
  select * into j from public.jobs where id = p_job;
  if not found or p_driver is null or (j.driver_id is distinct from p_driver and j.accepted_driver_id is distinct from p_driver) then
    return false;
  end if;
  perform public.record_driver_offer_event(j.tenant_id, p_job, p_driver, 'negotiation', e, p_driver, jsonb_build_object('via','negotiation'))
     from unnest(array['created','acknowledged','accepted']) e;
  return true;
end $$;
revoke all on function public.record_negotiated_assignment(uuid,uuid) from public, anon, authenticated;
grant execute on function public.record_negotiated_assignment(uuid,uuid) to service_role;

-- 3) Metrics computed in the database from recorded events (bounded, no row limits).
create or replace function public.driver_offer_metrics_v2(p_driver uuid, p_since timestamptz)
returns jsonb language sql stable security definer set search_path = public, pg_temp as $$
  with ev as (
    select job_id, offer_key, event, event_at from public.driver_offer_events
     where driver_id = p_driver and event_at >= p_since
  ), offers as (
    select job_id, offer_key,
           bool_or(event = 'acknowledged')        as ack,
           bool_or(event = 'delivery_attempted')  as attempted,
           max(event_at) filter (where event = 'accepted') as accepted_at,
           max(event_at) filter (where event = 'declined') as declined_at,
           bool_or(event = 'expired')             as expired
      from ev group by job_id, offer_key
  ), assignments as (                       -- identity: (driver, job), acceptance in the window
    select job_id, bool_or(declined_at > accepted_at) as handed_back
      from offers where ack and accepted_at is not null group by job_id
  ), classified as (                        -- exactly one class per assignment
    select a.job_id,
      case
        when j.status in ('cancelled','canceled') and j.metadata->>'cancelled_by_role' = 'driver'
             and j.metadata->>'cancelled_by' = p_driver::text then 'driver_cancelled'
        when a.handed_back then 'driver_handoff'
        when j.status not in ('cancelled','canceled') or j.id is null then 'not_cancelled'
        when j.metadata->>'cancelled_by_role' = 'customer' then 'customer'
        when j.metadata->>'cancelled_by_role' = 'admin' then 'admin'
        when j.metadata->>'cancelled_by_role' = 'driver' then 'other_driver'
        when j.no_show_status is not null then 'customer_no_show'
        else 'unattributed'
      end as class
    from assignments a left join public.jobs j on j.id = a.job_id
  )
  select jsonb_build_object(
    'acknowledgedOffers', (select count(*) from offers where ack),
    'deliveredAttempts',  (select count(*) from offers where attempted),
    'acceptedOffers',     (select count(*) from offers where ack and accepted_at is not null),
    'declinedOffers',     (select count(*) from offers where ack and declined_at is not null and accepted_at is null),
    'expiredOffers',      (select count(*) from offers where ack and expired and accepted_at is null),
    'acceptedBookings',   (select count(*) from assignments),
    'driverCancelledBookings', (select count(*) from classified where class = 'driver_cancelled'),
    'driverHandoffs',     (select count(*) from classified where class = 'driver_handoff'),
    'customerCancellations', (select count(*) from classified where class = 'customer'),
    'adminCancellations', (select count(*) from classified where class = 'admin'),
    'otherDriverCancellations', (select count(*) from classified where class = 'other_driver'),
    'customerNoShows',    (select count(*) from classified where class = 'customer_no_show'),
    'unattributedCancellations', (select count(*) from classified where class = 'unattributed'));
$$;
revoke all on function public.driver_offer_metrics_v2(uuid,timestamptz) from public, anon, authenticated;
grant execute on function public.driver_offer_metrics_v2(uuid,timestamptz) to service_role;

-- ===== END 20261267000000_driver_cancellation_attribution.sql =====

-- ===== BEGIN 20261268000000_cancellation_fee_quote.sql =====
-- Cancellation fee: one server-side quote from the published policy, frozen with the cancellation.
--
-- Fixes (found 2026-11-12): the API read jobs.cancellation_fee, a column the deployed jobs table does not
-- have, so no cancellation fee was ever quoted, captured or recorded; and a published policy version
-- could never become active (publish inserts enabled=false and nothing enabled it).
--
-- Rule (from the recorded design: late cancellation charges; early cancellation or no assigned driver
-- does not; grace_seconds / fee_minor / fee_cap_minor are policy fields). A fee is DUE only when:
--   * the CUSTOMER cancels (driver, admin and system cancellations never charge the customer — D9);
--   * an enabled, effective policy exists for the booking's tenant + market;
--   * the market's currency equals the booking currency (otherwise fail closed: no fee);
--   * a driver is assigned and accepted the booking more than grace_seconds before the cancellation.
-- Amount = least(fee_minor, fee_cap_minor, booking fare) in the booking currency's minor units.
-- exempt_reasons are NOT matched against the customer's free-text reason (it would let anyone avoid the
-- fee by typing a code); structured exemption is an open item.

create or replace function public.cancellation_fee_quote(
  p_job uuid, p_actor_role text, p_at timestamptz default now())
returns jsonb language plpgsql stable security definer set search_path = public, pg_temp as $$
declare j public.jobs%rowtype; p public.cancellation_policies; v_market_currency text; v_exp int;
        v_fee bigint; v_fare_minor bigint; v_grace_until timestamptz; v_code text;
begin
  select * into j from public.jobs where id = p_job;
  if not found then return jsonb_build_object('due', false, 'reasonCode', 'job_not_found', 'feeMinor', 0); end if;
  p := public.active_cancellation_policy(j.tenant_id, j.country_code);
  select upper(supported_currency) into v_market_currency from public.market_availability
   where country_code = j.country_code order by market_city nulls first limit 1;
  v_exp := public.wallet_currency_minor_exponent(j.currency_code);
  if p.id is not null and j.accepted_at is not null then
    v_grace_until := j.accepted_at + make_interval(secs => p.grace_seconds);
  end if;
  v_fee := case when p.id is null then 0 else least(p.fee_minor, coalesce(p.fee_cap_minor, p.fee_minor)) end;
  if coalesce(j.total_price, j.price) is not null and v_exp is not null then
    v_fare_minor := round(coalesce(j.total_price, j.price) * power(10::numeric, v_exp))::bigint;
    v_fee := least(v_fee, greatest(v_fare_minor, 0));
  end if;
  v_code := case
    when p.id is null then 'no_active_policy'
    when v_market_currency is null or v_market_currency <> upper(j.currency_code) or v_exp is null then 'currency_mismatch'
    when coalesce(p_actor_role, '') <> 'customer' then 'not_customer'
    when coalesce(j.driver_id, j.accepted_driver_id) is null then 'no_driver'
    when j.accepted_at is null then 'no_acceptance_time'
    when p_at <= v_grace_until then 'within_grace'
    when v_fee <= 0 then 'zero_fee'
    else 'due' end;
  return jsonb_build_object(
    'due', v_code = 'due',
    'reasonCode', v_code,
    'feeMinor', case when v_code = 'due' then v_fee else 0 end,
    'policyFeeMinor', coalesce(v_fee, 0),
    'currency', upper(j.currency_code),
    'exponent', v_exp,
    'policyVersion', p.version,
    'graceSeconds', p.grace_seconds,
    'graceUntil', v_grace_until,
    'driverAssigned', coalesce(j.driver_id, j.accepted_driver_id) is not null,
    'quotedAt', p_at);
end $$;
revoke all on function public.cancellation_fee_quote(uuid, text, timestamptz) from public, anon, authenticated;
grant execute on function public.cancellation_fee_quote(uuid, text, timestamptz) to service_role;

-- Same contract as 20261267000000, plus: the fee quote is computed under the row lock BEFORE the
-- status changes and frozen into metadata.cancellation_fee_quote in the same transaction.
create or replace function public.cancel_job_with_actor(
  p_job_id uuid, p_reason text, p_actor uuid, p_actor_role text)
returns boolean language plpgsql security definer set search_path = public, pg_temp as $$
declare j public.jobs%rowtype; ok boolean; q jsonb;
begin
  if p_actor is null or p_actor_role is null or p_actor_role not in ('customer','driver','admin') then
    raise exception 'invalid cancellation actor' using errcode = '22023';
  end if;
  select * into strict j from public.jobs where id = p_job_id for update;
  if p_actor_role = 'driver' and j.driver_id is distinct from p_actor and j.accepted_driver_id is distinct from p_actor then
    raise exception 'cancellation actor is not the assigned driver' using errcode = '42501';
  end if;
  if p_actor_role = 'customer' and j.customer_id is distinct from p_actor then
    raise exception 'cancellation actor is not the customer' using errcode = '42501';
  end if;
  q := public.cancellation_fee_quote(p_job_id, p_actor_role, now());
  ok := public.cancel_job_safely(p_job_id, p_reason);
  if ok and j.status not in ('cancelled','canceled') then
    update public.jobs
       set metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
             'cancelled_by', p_actor, 'cancelled_by_role', p_actor_role,
             'cancelled_driver_id', coalesce(j.driver_id, j.accepted_driver_id),
             'cancellation_fee_quote', q)
     where id = p_job_id;
  end if;
  return ok;
end $$;
revoke all on function public.cancel_job_with_actor(uuid,text,uuid,text) from public, anon, authenticated;
grant execute on function public.cancel_job_with_actor(uuid,text,uuid,text) to service_role;

-- Enabling/disabling a published version (service_role has no UPDATE on cancellation_policies).
-- The active policy stays "highest enabled version effective now"; history is never edited otherwise.
create or replace function public.set_cancellation_policy_enabled(p_policy uuid, p_tenant uuid, p_enabled boolean)
returns public.cancellation_policies language plpgsql security definer set search_path = public, pg_temp as $$
declare v public.cancellation_policies;
begin
  update public.cancellation_policies set enabled = p_enabled
   where id = p_policy and tenant_id = p_tenant returning * into v;
  if not found then raise exception 'cancellation policy not found for tenant' using errcode = 'P0002'; end if;
  return v;
end $$;
revoke all on function public.set_cancellation_policy_enabled(uuid,uuid,boolean) from public, anon, authenticated;
grant execute on function public.set_cancellation_policy_enabled(uuid,uuid,boolean) to service_role;

-- ===== END 20261268000000_cancellation_fee_quote.sql =====

-- ===== BEGIN 20261269000000_merge_cash_pilot_with_roadmap_cash.sql =====
-- 20261269000000_merge_cash_pilot_with_roadmap_cash
-- GENERATED by scripts/migration-merge/generate-cash-roadmap-merge.cjs — do not edit by hand.
-- Runs AFTER both the roadmap chain (through 20261263000000) and the cash-ride chain
-- (20261266000000..20261266300000), in either order, and installs one merged body for each function
-- both chains replace. Sources (verbatim, then asserted single edits):
--   enforce_job_payment_eligibility  <- supabase/migrations/20261255500000_cash_acquisition_eligibility.sql
--   enforce_ride_cash_credit_v1e     <- supabase/migrations/20261263000000_courier_cash_reassignment.sql
--   reserve_cash_job_credit_v1e      <- supabase/migrations/20261263000000_courier_cash_reassignment.sql
--   driver_cash_credit_status_v1f    <- supabase/migrations/20261266000000_driver_cash_credit_market_pilot.sql
-- Enables nothing: courier_enabled defaults to false and no market row is written.
DO $pre$ BEGIN
  IF to_regclass('public.driver_cash_credit_markets_v1e') IS NULL OR to_regclass('public.cash_ride_fee_holds_v1e') IS NULL
     OR to_regprocedure('public.cash_ride_acquirable_v1e(public.jobs)') IS NULL THEN
    RAISE EXCEPTION 'merge requires the cash-ride chain (20261266000000..20261266300000) first';
  END IF;
  IF to_regprocedure('public.reassign_cash_job_credit_v1f(uuid,uuid)') IS NULL
     OR NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.driver_cash_credit_holds_v1e'::regclass AND pg_get_constraintdef(oid) LIKE '%reassigned%') THEN
    RAISE EXCEPTION 'merge requires the roadmap cash chain (through 20261263000000) first';
  END IF;
END $pre$;

ALTER TABLE public.driver_cash_credit_markets_v1e ADD COLUMN IF NOT EXISTS courier_enabled boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.driver_cash_credit_markets_v1e.courier_enabled IS
  'Courier (delivery/errand) cash with cash credit and no card hold. Off unless explicitly enabled (business decision D10).';

-- Is cash enabled for this service in this market? Ride: the market pilot. Courier: the market pilot AND courier_enabled.
CREATE OR REPLACE FUNCTION public.cash_service_enabled_v1e(p_slug text, p_country text, p_currency text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT coalesce(public.driver_cash_credit_market_enabled_v1e(p_country,p_currency), false)
    AND CASE WHEN p_slug = 'ride' THEN true
             WHEN p_slug IN ('delivery','errand') THEN coalesce((SELECT m.courier_enabled FROM public.driver_cash_credit_markets_v1e m
                    WHERE m.country_code = p_country AND m.currency_code = p_currency), false)
             ELSE false END $$;
REVOKE ALL ON FUNCTION public.cash_service_enabled_v1e(text,text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.cash_service_enabled_v1e(text,text,text) TO service_role;

-- May this cash job acquire a driver? Ride: the cash-ride plan rule. Courier: enabled + full cash custody.
CREATE OR REPLACE FUNCTION public.cash_acquisition_allowed_v1e(j public.jobs) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT coalesce(CASE (SELECT s.slug FROM public.service_types s WHERE s.id = j.service_type_id)
   WHEN 'ride' THEN public.cash_ride_acquirable_v1e(j)
   WHEN 'delivery' THEN public.cash_service_enabled_v1e('delivery', j.country_code, j.currency_code)
        AND j.payment_intent_id IS NULL AND j.metadata->>'cash_collection_mode' = 'full_customer_charge'
   WHEN 'errand' THEN public.cash_service_enabled_v1e('errand', j.country_code, j.currency_code)
        AND j.payment_intent_id IS NULL AND j.metadata->>'cash_collection_mode' = 'full_customer_charge'
   ELSE false END, false) $$;
REVOKE ALL ON FUNCTION public.cash_acquisition_allowed_v1e(public.jobs) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.cash_acquisition_allowed_v1e(public.jobs) TO service_role;

CREATE OR REPLACE FUNCTION public.enforce_job_payment_eligibility()
RETURNS trigger LANGUAGE plpgsql AS $function$
BEGIN
    IF NEW.driver_id IS NOT NULL
       AND OLD.driver_id IS DISTINCT FROM NEW.driver_id
       AND NEW.status IN ('assigned', 'accepted') THEN
        -- Non-cash: the electronic-payment status gate (unchanged).
        -- Cash Ride: only through cash_ride_acquirable_v1e (cash-ride plan: enabled pilot market, full
        --   cash custody, no PaymentIntent, authorised card fee hold).
        -- Cash courier (delivery/errand): only where courier cash is explicitly enabled for the market;
        --   cash custody/credit is then verified by enforce_ride_cash_credit_v1e.
        IF (NEW.payment_method IS DISTINCT FROM 'cash'
            AND NEW.payment_status NOT IN (
                'paid', 'wallet_funded', 'authorized', 'requires_capture', 'succeeded', 'captured'
            ))
           OR (NEW.payment_method = 'cash' AND NOT public.cash_acquisition_allowed_v1e(NEW)) THEN
            RAISE EXCEPTION 'Job is not payment-eligible for driver acquisition'
                USING ERRCODE = 'MB003',
                      DETAIL = 'payment_eligibility';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_ride_cash_credit_v1e() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE h public.driver_cash_credit_holds_v1e%ROWTYPE; driver uuid; slug text;
BEGIN
 SELECT * INTO h FROM public.driver_cash_credit_holds_v1e WHERE job_id=NEW.id AND status='held' ORDER BY created_at DESC LIMIT 1;
 IF FOUND THEN
  IF NOT public.cash_credit_service_writer_v1e() THEN RAISE EXCEPTION 'Cash transitions require the server role' USING ERRCODE='CE002'; END IF;
  IF NEW.status IS NULL THEN RAISE EXCEPTION 'Cash booking status missing' USING ERRCODE='CE006'; END IF;
  IF NEW.status IN ('cancelled','canceled','expired','failed','no_driver_found') THEN
   IF h.status='settled' THEN RAISE EXCEPTION 'Settled cash ride requires refund review' USING ERRCODE='CE005'; END IF;
   IF h.status='held' THEN PERFORM public.resolve_cash_job_credit_v1e(NEW.id,'released'); END IF;
   RETURN NEW;
  END IF;
  IF h.status='released' OR (h.status='settled' AND NEW.status NOT IN ('completed','delivered','settled')) THEN RAISE EXCEPTION 'Resolved cash ride cannot reopen' USING ERRCODE='CE005'; END IF;
  IF NEW.driver_id IS NOT NULL AND NEW.accepted_driver_id IS NOT NULL AND NEW.driver_id<>NEW.accepted_driver_id THEN RAISE EXCEPTION 'Conflicting accepted drivers' USING ERRCODE='CE005'; END IF;
  IF NEW.metadata->>'cash_collection_mode' IS DISTINCT FROM 'full_customer_charge' OR NEW.payment_intent_id IS NOT NULL THEN RAISE EXCEPTION 'Cash custody/payment mode changed' USING ERRCODE='CE005'; END IF;
  IF NEW.payment_method IS DISTINCT FROM 'cash' OR NEW.fare_breakdown IS DISTINCT FROM h.fare_snapshot
     OR NEW.tenant_id IS DISTINCT FROM h.tenant_id OR NEW.currency_code IS DISTINCT FROM h.currency_code
     OR NEW.country_code IS DISTINCT FROM h.country_code OR coalesce(NEW.driver_id,NEW.accepted_driver_id) IS DISTINCT FROM h.driver_id THEN
   RAISE EXCEPTION 'Cash reservation requires explicit reconciliation before changing terms' USING ERRCODE='CE005'; END IF;
  IF NEW.status IN ('completed','delivered','settled') AND h.status='held' THEN PERFORM public.resolve_cash_job_credit_v1e(NEW.id,'settled'); END IF;
  RETURN NEW;
 END IF;
 -- Reopen guard for a resolved (released/settled) hold whose row is no longer live.
 IF EXISTS(SELECT 1 FROM public.driver_cash_credit_holds_v1e WHERE job_id=NEW.id AND status IN ('released','settled')) THEN
  IF EXISTS(SELECT 1 FROM public.driver_cash_credit_holds_v1e WHERE job_id=NEW.id AND status='released')
     AND NEW.status IN ('completed','delivered','settled') THEN
   RAISE EXCEPTION 'Released cash ride cannot complete' USING ERRCODE='CE005'; END IF;
  IF EXISTS(SELECT 1 FROM public.driver_cash_credit_holds_v1e WHERE job_id=NEW.id AND status='settled')
     AND NEW.status IN ('cancelled','canceled','expired','failed','no_driver_found') THEN
   RAISE EXCEPTION 'Settled cash ride cannot be cancelled' USING ERRCODE='CE005'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.payment_method IS DISTINCT FROM 'cash' THEN RETURN NEW; END IF;
 SELECT st.slug INTO slug FROM public.service_types st WHERE st.id=NEW.service_type_id;
 IF slug IS NULL OR slug NOT IN ('ride','delivery','errand') THEN RETURN NEW; END IF;
 IF NOT public.cash_service_enabled_v1e(slug,NEW.country_code,NEW.currency_code) THEN
  -- Restored disabled-acquisition gate (20261255600000, dropped by 20261255700000): a cash job
  -- gaining a driver where cash is not enabled must fail, not silently skip the reservation.
  driver:=coalesce(NEW.driver_id,NEW.accepted_driver_id);
  IF driver IS NOT NULL AND (TG_OP='INSERT' OR coalesce(OLD.driver_id,OLD.accepted_driver_id) IS NULL)
     AND NEW.status IN ('assigned','accepted','heading_to_pickup','driver_en_route','arrived','in_progress','completed','delivered','settled') THEN
   RAISE EXCEPTION 'Cash is not enabled for this service in this market' USING ERRCODE='CE001';
  END IF;
  RETURN NEW;
 END IF;
 IF NOT public.cash_credit_service_writer_v1e() THEN RAISE EXCEPTION 'Cash acceptance requires the server role' USING ERRCODE='CE002'; END IF;
 driver:=coalesce(NEW.driver_id,NEW.accepted_driver_id);
 IF driver IS NOT NULL AND NEW.status IN ('assigned','accepted','heading_to_pickup','driver_en_route','arrived','in_progress','completed','delivered','settled') THEN
  PERFORM public.reserve_cash_job_credit_v1e(NEW.id,driver);
 END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.reserve_cash_job_credit_v1e(p_job_id uuid,p_driver_id uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE j public.jobs%ROWTYPE; enrol public.driver_cash_credit_enrolments_v1e%ROWTYPE; p jsonb; terms jsonb; balance jsonb; h public.driver_cash_credit_holds_v1e%ROWTYPE; v_id uuid; event uuid; need bigint; driver uuid;
BEGIN
 SELECT * INTO STRICT j FROM public.jobs WHERE id=p_job_id FOR UPDATE;
 driver:=coalesce(j.driver_id,j.accepted_driver_id);
 IF driver IS DISTINCT FROM p_driver_id OR p_driver_id IS NULL OR (j.driver_id IS NOT NULL AND j.accepted_driver_id IS NOT NULL AND j.driver_id<>j.accepted_driver_id)
 OR j.payment_method IS DISTINCT FROM 'cash' OR j.status IS NULL OR j.status NOT IN ('assigned','accepted','heading_to_pickup','driver_en_route','arrived','in_progress','completed','delivered','settled') THEN
  RAISE EXCEPTION 'Cash booking/driver is not eligible' USING ERRCODE='CE002'; END IF;
 -- Passenger Ride keeps its branch; verified courier services are delivery/errand.
 IF NOT EXISTS(SELECT 1 FROM public.service_types WHERE id=j.service_type_id AND slug IN ('ride','delivery','errand')) THEN
  RAISE EXCEPTION 'Cash credit supports Ride, delivery and errand only' USING ERRCODE='CE002'; END IF;
 IF NOT public.cash_service_enabled_v1e((SELECT slug FROM public.service_types WHERE id=j.service_type_id),j.country_code,j.currency_code) THEN
  RAISE EXCEPTION 'Cash credit pilot disabled for this service in this market' USING ERRCODE='CE001'; END IF;
 PERFORM public.driver_cash_credit_lock_v1e(j.tenant_id,p_driver_id,j.currency_code);
 SELECT to_jsonb(x) INTO p FROM public.profiles x WHERE id=p_driver_id;
 SELECT * INTO enrol FROM public.driver_cash_credit_enrolments_v1e WHERE tenant_id=j.tenant_id AND driver_id=p_driver_id AND country_code=j.country_code AND currency_code=j.currency_code FOR SHARE;
 IF p IS NULL OR p->>'role' IS DISTINCT FROM 'driver' OR NULLIF(p->>'registration_activated_at','') IS NULL
 OR NOT public.driver_job_market_matches_v23(p,to_jsonb(j))
 OR NOT EXISTS(SELECT 1 FROM public.market_availability m WHERE m.country_code=j.country_code AND upper(m.supported_currency)=j.currency_code)
 OR enrol.driver_id IS NULL OR NOT enrol.enabled OR enrol.consented_at>now() THEN
  RAISE EXCEPTION 'Driver cash credit is not approved for this tenant/market' USING ERRCODE='CE002'; END IF;
 terms:=public.cash_credit_terms_v1e(j.fare_breakdown,j.currency_code);need:=(terms->>'required')::bigint;
 IF j.fare_breakdown ? 'driverCommissionPolicy' AND j.fare_breakdown->'driverCommissionPolicy'->>'driverId' IS DISTINCT FROM p_driver_id::text THEN
  RAISE EXCEPTION 'Frozen commission belongs to another driver' USING ERRCODE='CE003'; END IF;
 IF j.agreed_fare IS NOT NULL AND public.cash_credit_minor_v1e(to_jsonb(j.agreed_fare),j.currency_code)<>(terms->>'charge')::bigint THEN
  RAISE EXCEPTION 'Agreed fare does not match frozen cash terms' USING ERRCODE='CE003'; END IF;
 SELECT * INTO h FROM public.driver_cash_credit_holds_v1e WHERE job_id=j.id AND status='held' FOR UPDATE;
 IF FOUND THEN
  IF h.driver_id<>p_driver_id OR h.tenant_id<>j.tenant_id OR h.currency_code<>j.currency_code OR h.country_code<>j.country_code OR h.fare_snapshot IS DISTINCT FROM j.fare_breakdown THEN
   RAISE EXCEPTION 'Cash reservation replay terms changed' USING ERRCODE='CE005'; END IF;
  RETURN h.id;
 END IF;
 IF j.metadata->>'cash_collection_mode' IS DISTINCT FROM 'full_customer_charge' OR j.payment_intent_id IS NOT NULL OR j.payment_status IS NULL OR j.payment_status NOT IN ('pending','cash_due','cash_pending') THEN
  RAISE EXCEPTION 'Explicit full-cash custody and no digital payment required' USING ERRCODE='CE002'; END IF;
 IF j.status IN ('completed','delivered','settled') THEN RAISE EXCEPTION 'Cannot create a new cash hold after completion' USING ERRCODE='CE006'; END IF;
 balance:=public.driver_cash_credit_balance_v1e(j.tenant_id,p_driver_id,j.currency_code);
 IF NOT (balance->>'consistent')::boolean OR (balance->>'deficitMinor')::numeric>0 THEN RAISE EXCEPTION 'Cash credit requires reconciliation' USING ERRCODE='CE006'; END IF;
 IF (balance->>'availableMinor')::numeric<need THEN RAISE EXCEPTION 'Top up driver cash credit before accepting this cash ride' USING ERRCODE='CE004'; END IF;
 v_id:=gen_random_uuid();
 IF need>0 THEN
  event:=public.post_wallet_event('cash-hold:'||v_id::text,'cash_credit_reserve',j.tenant_id,p_driver_id,j.currency_code,
   jsonb_build_array(jsonb_build_object('accountPurpose','driver_cash_credit','amountMinor',-need),jsonb_build_object('accountPurpose','driver_cash_credit_reserved','amountMinor',need)));
 END IF;
 INSERT INTO public.driver_cash_credit_holds_v1e(id,job_id,tenant_id,driver_id,country_code,currency_code,fare_snapshot,enrolment_terms_version,enrolment_consented_at,customer_charge_minor,commission_minor,platform_fee_minor,driver_entitlement_minor,required_credit_minor,reserve_event_id)
 VALUES(v_id,j.id,j.tenant_id,p_driver_id,j.country_code,j.currency_code,j.fare_breakdown,enrol.terms_version,enrol.consented_at,(terms->>'charge')::bigint,(terms->>'commission')::bigint,(terms->>'fee')::bigint,(terms->>'net')::bigint,need,event);
 RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION public.driver_cash_credit_status_v1f(p_driver_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE p public.profiles%ROWTYPE; v_country text; v_currency text; currencies integer; approved boolean; b jsonb;
BEGIN
 SELECT * INTO p FROM public.profiles WHERE id=p_driver_id;
 IF NOT FOUND OR p.role IS DISTINCT FROM 'driver' THEN RAISE EXCEPTION 'Driver access required' USING ERRCODE='CE002'; END IF;
 v_country:=upper(btrim(coalesce(nullif(p.registration_country_code,''),p.country_code,'')));
 IF p.tenant_id IS NULL OR v_country !~ '^[A-Z]{2}$' THEN RAISE EXCEPTION 'Driver market unresolved' USING ERRCODE='CE002'; END IF;
 SELECT count(DISTINCT upper(supported_currency)),min(upper(supported_currency)) INTO currencies,v_currency
 FROM public.market_availability WHERE country_code=v_country;
 IF currencies<>1 OR v_currency IS NULL OR v_currency !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'Driver currency unresolved' USING ERRCODE='CE002'; END IF;
 approved:=p.registration_activated_at IS NOT NULL AND EXISTS(
  SELECT 1 FROM public.driver_cash_credit_enrolments_v1e e WHERE e.tenant_id=p.tenant_id AND e.driver_id=p.id
   AND e.country_code=v_country AND e.currency_code=v_currency AND e.enabled AND e.consented_at<=now());
 b:=public.driver_cash_credit_balance_v1e(p.tenant_id,p.id,v_currency);
 RETURN jsonb_build_object('tenantId',p.tenant_id,'driverId',p.id,'country',v_country,'currency',v_currency,
  'pilotEnabled',public.driver_cash_credit_market_enabled_v1e(v_country,v_currency),'enrolled',approved,'balance',b,
  'topupAvailable',false,'payoutAvailable',false,'acceptanceAuthority','database');
END $_$;


